import {CHANNELS,SEGMENTS,STAGES,OPEN,canManage,inScope,load,chooseAgent,assign,claim,changeOwner,validateClient,duplicates,normalizePhone,audit,seed} from './domain.mjs';
const $=s=>document.querySelector(s),key='kalbir-crm-piloto-v1';let s;let storageWarning='';
try{s=JSON.parse(localStorage.getItem(key));if(s?.version!==1||!Array.isArray(s.clients)||!Array.isArray(s.users))s=seed();}catch{s=seed();storageWarning='Não foi possível carregar os dados locais. A demonstração foi iniciada novamente.';}
let actorId='g1',page='overview',query='',clientFilter='Todos',ticketFilter='Todos';
const actor=()=>s.users.find(u=>u.id===actorId),user=id=>s.users.find(u=>u.id===id),client=id=>s.clients.find(c=>c.id===id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const when=t=>t?new Date(t).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'Sem agendamento';
const initials=n=>n.split(' ').filter(Boolean).slice(0,2).map(v=>v[0]).join('');
const scoped=arr=>arr.filter(x=>inScope(actor(),x));
const clients=()=>scoped(s.clients).filter(c=>canManage(actor())||c.ownerId===actorId||s.tickets.some(t=>t.clientId===c.id&&(t.assigneeId===actorId||t.status==='Em fila')));
const tickets=()=>scoped(s.tickets).filter(t=>canManage(actor())||t.assigneeId===actorId||t.status==='Em fila');
const opportunities=()=>scoped(s.opportunities).filter(o=>canManage(actor())||o.ownerId===actorId);
function save(){try{localStorage.setItem(key,JSON.stringify(s));storageWarning='';}catch{storageWarning='Armazenamento indisponível. As mudanças desta sessão podem não ser preservadas.';toast(storageWarning);}}
let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
const icons={overview:'◫',work:'☷',queue:'⇥',clients:'♧',pipeline:'▥',team:'♙',integrations:'⌘',audit:'↺'};
const labels={overview:'Visão geral',work:'Meu trabalho',queue:'Fila de atendimento',clients:'Clientes e carteiras',pipeline:'Oportunidades',team:'Equipe e disponibilidade',integrations:'Canais e integrações',audit:'Histórico de alterações'};
const chip=(text,cls='')=>`<span class="chip ${cls}">${esc(text)}</span>`;
const statusChip=t=>chip(t,t==='Em fila'?'amber':t==='Encerrado'?'muted':t==='Em atendimento'?'green':'');
const ownerLabel=id=>user(id)?.name||'Sem responsável';
const btn=(label,action,id='',cls='secondary')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const empty=(title,desc)=>`<div class="empty"><span>◇</span><h3>${title}</h3><p>${desc}</p></div>`;
function render(){
 if(!canManage(actor())&&['team','audit'].includes(page))page='work';
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" aria-label="Kalbir início"><span class="brand-mark">K</span><span>KALBIR<small>CENTRAL DE VENDAS</small></span></a><div class="workspace"><span class="workspace-icon">K</span><div>Kalbir Atacado<small>Loja piloto · Fortaleza</small></div><span class="live-dot"></span></div><p class="nav-label">OPERAÇÃO</p><nav>${Object.keys(labels).filter(k=>!['team','audit'].includes(k)||canManage(actor())).map(k=>`<button data-page="${k}" class="nav-item ${page===k?'active':''}"><span>${icons[k]}</span>${labels[k]}${k==='queue'?`<b>${tickets().filter(t=>t.status==='Em fila').length}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="pilot-note"><span>◈</span><div>Construído para seu time<small>Piloto de televendas · versão 0.1</small></div></div><div class="profile"><span class="avatar">${initials(actor().name)}</span><div>${esc(actor().name)}<small>${actor().role==='gestor'?'Gestão comercial':actor().role==='gerente'?'Gerência da loja':'Vendas'}</small></div></div></div></aside><div class="shell"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Abrir menu">☰</button><div class="breadcrumb">Kalbir Atacado <span>/</span> <strong>${labels[page]}</strong></div><div class="top-actions"><span class="demo-tag">DEMONSTRAÇÃO</span><label class="sr-only" for="actor-select">Simular perfil</label><select id="actor-select" aria-label="Simular perfil de acesso">${s.users.map(u=>`<option value="${u.id}" ${u.id===actorId?'selected':''}>${esc(u.name)} · ${u.role}</option>`).join('')}</select></div></header><main><div class="demo-banner"><span>◉</span><p>Dados fictícios · alterações salvas somente neste navegador. Perfis simulados, sem login real.</p>${btn('Exportar dados','export','','text-button')}</div>${storageWarning?`<p role="alert" class="warning">${esc(storageWarning)}</p>`:''}<div id="page-content">${({overview:overview,work:work,queue:queue,clients:clientPage,pipeline:pipeline,team:team,integrations:integrations,audit:auditPage}[page])()}</div><footer>Kalbir CRM <span>•</span> Atendimento próximo. Vendas organizadas.</footer></main></div>`;
}
document.addEventListener('change', e=>{if(e.target.id==='self-availability'){actor().availability=e.target.value;audit(s,actor(),'Disponibilidade alterada',actor().availability);save();render();toast('Sua disponibilidade foi atualizada.');}});
const renderBase=render;render=function(){renderBase();if(actor().role==='vendedora'){document.querySelector('.top-actions').insertAdjacentHTML('afterbegin', '<label class="sr-only" for="self-availability">Minha disponibilidade</label><select id="self-availability" aria-label="Minha disponibilidade">'+['Disponível','Lanche','Almoço','Ausente'].map(v=>'<option '+(v===actor().availability?'selected':'')+'>'+v+'</option>').join('')+'</select>');}};
function heading(eyebrow,title,desc,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${desc}</p></div><div class="heading-actions">${actions}</div></div>`;}
function stat(label,value,desc,icon,accent=''){return `<article class="stat ${accent}"><div>${label}<span>${icon}</span></div><strong>${value}</strong><small>${desc}</small></article>`;}
function overview(){const ts=tickets(),os=opportunities(),open=ts.filter(t=>OPEN.includes(t.status)),pending=ts.filter(t=>t.status==='Em fila'),won=os.filter(o=>o.stage==='Ganho');
 return heading('SEU DIA, EM PERSPECTIVA',`Bom trabalho, ${esc(actor().name.split(' ')[0])}.`,'Acompanhe a operação e mantenha o próximo contato em dia.',btn('+ Novo atendimento','new-ticket','','primary'))+`<div class="stats">${stat('Em andamento',open.length,'Atendimentos abertos da operação','↗','accent')}${stat('Na fila',pending.length,'Aguardando uma pessoa responsável','⇥')}${stat('Clientes na carteira',clients().length,'Cadastros visíveis neste perfil','♧')}${stat('Em negociação',money(os.filter(o=>!['Ganho','Perdido'].includes(o.stage)).reduce((n,o)=>n+o.value,0)),'Valor estimado · não é faturamento','◈')}</div><div class="overview-grid"><section class="panel"><div class="section-title"><div><h2>Precisam de atenção</h2><p>Próximos passos da sua operação</p></div>${btn('Ver fila →','go-queue','','text-button')}</div>${pending.length?pending.slice(0,4).map(t=>ticketRow(t)).join(''):empty('Fila em dia','Nenhum atendimento aguardando distribuição.')}</section><section class="focus-card"><div class="focus-top"><span class="chip light">FOCO DO DIA</span><span>↗</span></div><h2>Uma boa venda começa com um bom retorno.</h2><p>Organize o próximo contato de cada cliente e evite deixar oportunidades paradas.</p>${btn('Organizar meus atendimentos →','go-work','','light-button')}<div class="focus-bottom"><span>◎</span><small>Carteira preservada.<br>Equipe conectada.</small></div></section></div><div class="overview-grid lower"><section class="panel"><div class="section-title"><div><h2>Disponibilidade da equipe</h2><p>Distribuição considera carga e disponibilidade</p></div>${canManage(actor())?btn('Gerenciar →','go-team','','text-button'):''}</div>${scoped(s.users).filter(u=>u.role==='vendedora').map(u=>`<div class="agent-row"><span class="avatar pale">${initials(u.name)}</span><div><strong>${esc(u.name)}</strong><small>${esc(u.availability)}</small></div><div class="load"><strong>${load(s,u.id)} <span>/ ${u.capacity}</span></strong><div class="load-bar"><i style="width:${Math.min(100,load(s,u.id)/u.capacity*100)}%"></i></div></div></div>`).join('')}</section><section class="panel"><div class="section-title"><div><h2>Funil comercial</h2><p>${os.length} oportunidades · ${won.length} ganhas</p></div>${btn('Abrir funil →','go-pipeline','','text-button')}</div><div class="funnel-summary">${STAGES.filter(st=>!['Ganho','Perdido'].includes(st)).map((st,i)=>{const n=os.filter(o=>o.stage===st).length;return `<div><span>${st}</span><div class="funnel-track"><i style="width:${n?Math.max(12,n/Math.max(os.length,1)*100):0}%;opacity:${1-i*.12}"></i></div><b>${n}</b></div>`;}).join('')}</div></section></div>`;
}
function ticketRow(t){const c=client(t.clientId);return `<button class="ticket-row" data-action="ticket" data-id="${t.id}"><span class="avatar ${t.priority==='Alta'?'warm':'pale'}">${initials(c.name)}</span><div class="row-main"><strong>${esc(c.name)}</strong><small>${esc(t.subject)}</small></div><div class="row-meta">${chip(c.channel)}<small>${esc(ownerLabel(t.assigneeId))}</small></div><span class="arrow">↗</span></button>`;}
function searchBar(placeholder,extra=''){return `<div class="toolbar"><div class="search-box"><span>⌕</span><input id="search" type="search" placeholder="${placeholder}" value="${esc(query)}" aria-label="${placeholder}"></div>${extra}</div>`;}
const match=t=>{const c=client(t.clientId);return `${c.name} ${t.subject} ${c.channel}`.toLowerCase().includes(query.toLowerCase());};
function work(){const mine=tickets().filter(t=>canManage(actor())?t.assigneeId:t.assigneeId===actorId);const filtered=mine.filter(match).filter(t=>ticketFilter==='Todos'||t.status===ticketFilter);
 return heading('ROTINA COMERCIAL','Meu trabalho','Atendimentos, pendências e retornos em um só lugar.',btn('+ Novo atendimento','new-ticket','','primary'))+searchBar('Buscar cliente ou assunto',`<select id="ticket-filter" aria-label="Filtrar estado">${['Todos',...OPEN,'Encerrado'].map(x=>`<option ${x===ticketFilter?'selected':''}>${x}</option>`).join('')}</select>`)+`<div class="tabs"><span class="selected">${canManage(actor())?'Atendimentos da equipe':'Meus atendimentos'} <b>${mine.length}</b></span><span>Retornos agendados <b>${mine.filter(t=>t.nextAt&&t.status!=='Encerrado').length}</b></span></div><div class="ticket-grid">${filtered.length?filtered.map(ticketCard).join(''):empty('Nenhum atendimento por aqui','Use outro filtro ou registre um novo contato.')}</div>`;
}
function ticketCard(t){const c=client(t.clientId);const due=t.nextAt&&new Date(t.nextAt)<new Date()&&t.status!=='Encerrado';return `<article class="ticket-card"><div class="card-top">${statusChip(t.status)}<span class="tiny">#${t.id.replace('t','')}</span></div><div class="client-line"><span class="avatar pale">${initials(c.name)}</span><div><h3>${esc(c.name)}</h3><small>${esc(c.channel)}</small></div></div><p class="subject">${esc(t.subject)}</p><div class="card-info"><span>Carteira</span><strong>${esc(ownerLabel(c.ownerId))}</strong><span>Atendimento</span><strong>${esc(ownerLabel(t.assigneeId))}</strong></div>${t.nextAt?`<div class="return ${due?'overdue':''}">◷ ${when(t.nextAt)}<small>${esc(t.nextAction)}</small></div>`:''}<div class="card-footer">${t.priority==='Alta'?chip('Prioridade alta','amber'):`<small>Registrado ${when(t.createdAt)}</small>`}${btn('Abrir →','ticket',t.id,'text-button')}</div></article>`;}
function queue(){const q=tickets().filter(t=>t.status==='Em fila').filter(match).sort((a,b)=>(b.priority==='Alta')-(a.priority==='Alta')||a.createdAt-b.createdAt);return heading('DISTRIBUIÇÃO E COBERTURA','Fila de atendimento','Clientes sem atendimento atribuído. A carteira original é preservada.',`${canManage(actor())?btn('Distribuir automaticamente','auto-assign','','secondary'):''}${btn('+ Registrar entrada','new-ticket','','primary')}`)+`<div class="info-line">ⓘ A fila reúne entradas registradas no CRM. Mensagens dos canais externos ainda não chegam automaticamente.</div>`+searchBar('Buscar na fila')+`<div class="ticket-grid">${q.length?q.map(t=>{const c=client(t.clientId);const a=chooseAgent(s,c);return `<article class="ticket-card"><div class="card-top">${chip(t.priority==='Alta'?'Prioridade alta':'Aguardando','amber')}<span class="tiny">#${t.id.replace('t','')}</span></div><div class="client-line"><span class="avatar warm">${initials(c.name)}</span><div><h3>${esc(c.name)}</h3><small>${esc(c.channel)}</small></div></div><p class="subject">${esc(t.subject)}</p><div class="card-info"><span>Carteira</span><strong>${esc(ownerLabel(c.ownerId))}</strong><span>Sugestão</span><strong>${esc(a?.name||'Aguardar disponibilidade')}</strong></div><p class="tiny">Entrada: ${when(t.createdAt)}</p><div class="card-footer">${btn('Detalhes','ticket',t.id,'text-button')}${actor().role==='vendedora'?btn('Puxar atendimento','claim',t.id,'primary'):btn('Atribuir','assign',t.id,'primary')}</div></article>`;}).join(''):empty('Fila organizada','Todos os atendimentos já têm responsável.')}</div>`;}
function clientPage(){const cs=clients().filter(c=>`${c.name} ${c.contact} ${c.phone} ${c.company} ${c.email} ${c.handle}`.toLowerCase().includes(query.toLowerCase())).filter(c=>clientFilter==='Todos'||(clientFilter==='Sem responsável'?!c.ownerId:c.ownerId===clientFilter));return heading('RELACIONAMENTO E RECORRÊNCIA','Clientes e carteiras','Conheça cada cliente e mantenha a responsabilidade comercial clara.',btn('+ Novo cliente','new-client','','primary'))+searchBar('Buscar por nome, empresa ou contato',`<select id="client-filter" aria-label="Filtrar carteira"><option>Todos</option><option ${clientFilter==='Sem responsável'?'selected':''}>Sem responsável</option>${scoped(s.users).filter(u=>u.role==='vendedora').map(u=>`<option value="${u.id}" ${clientFilter===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select>`)+`<section class="panel table-panel"><div class="table-caption"><strong>${cs.length} clientes</strong><small>Dados demonstrativos · sem conexão ao ERP</small></div><div class="table-scroll"><table><thead><tr><th>Cliente / empresa</th><th>Contato e canal</th><th>Segmento</th><th>Carteira</th><th>Status</th><th><span class="sr-only">Ação</span></th></tr></thead><tbody>${cs.map(c=>`<tr><td><div class="client-line"><span class="avatar pale">${initials(c.name)}</span><div><strong>${esc(c.name)}</strong><small>${esc(c.contact||c.company)}</small></div></div></td><td>${chip(c.channel)}<small>${esc(c.phone||c.email||c.handle||'Contato a completar')}</small></td><td>${esc(c.segments.join(', ')||'Não informado')}</td><td>${esc(ownerLabel(c.ownerId))}</td><td>${chip(c.status,c.status==='Cliente ativo'?'green':'')}${c.doNotContact?chip('Não contatar','amber'):''}</td><td>${btn('Ver ficha →','client',c.id,'text-button')}</td></tr>`).join('')}</tbody></table></div>${!cs.length?empty('Nenhum cliente encontrado','Ajuste a busca ou cadastre um cliente.'):''}</section>`;}
function pipeline(){const os=opportunities().filter(o=>`${o.title} ${client(o.clientId).name}`.toLowerCase().includes(query.toLowerCase()));return heading('DO PRIMEIRO CONTATO À VENDA','Oportunidades','Acompanhe negociações sem confundir o encerramento da conversa com o resultado da venda.',btn('+ Nova oportunidade','new-opportunity','','primary'))+`<div class="info-line">ⓘ Valores estimados ou informados manualmente. Preços e estoque não estão conectados ao WinThor.</div>`+searchBar('Buscar oportunidade ou cliente')+`<div class="kanban">${STAGES.map(st=>{const items=os.filter(o=>o.stage===st);return `<section class="kanban-col"><div class="kanban-heading"><h2>${st}</h2><b>${items.length}</b></div><p class="kanban-value">${money(items.reduce((a,o)=>a+o.value,0))}</p>${items.map(o=>`<button class="deal-card" data-action="opportunity" data-id="${o.id}"><span class="tiny">${esc(client(o.clientId).name)}</span><h3>${esc(o.title)}</h3><strong>${money(o.value)}</strong><p>${esc(o.nextAction||'Definir próxima ação')}</p><div><span class="avatar mini">${initials(ownerLabel(o.ownerId))}</span><small>${esc(ownerLabel(o.ownerId))}</small><span>↗</span></div></button>`).join('')}${!items.length?'<p class="kanban-empty">Nenhuma oportunidade</p>':''}</section>`;}).join('')}</div>`;}
function team(){return heading('PESSOAS E CAPACIDADE','Equipe e disponibilidade','Intervalos suspendem novos recebimentos. Atendimentos existentes continuam atribuídos.',btn('+ Adicionar vendedora','new-user','','primary'))+`<div class="team-grid">${scoped(s.users).filter(u=>u.role==='vendedora').map(u=>`<article class="panel agent-card"><span class="avatar large pale">${initials(u.name)}</span><h2>${esc(u.name)}</h2><p>Vendedora · Loja piloto</p><label>Disponibilidade<select data-user="${u.id}" class="availability">${['Disponível','Lanche','Almoço','Ausente'].map(v=>`<option ${v===u.availability?'selected':''}>${v}</option>`).join('')}</select></label><div class="capacity-row"><strong>${load(s,u.id)} <small>em andamento</small></strong><label>Limite<input class="capacity" data-user="${u.id}" type="number" min="1" max="50" value="${u.capacity}" aria-label="Limite de ${esc(u.name)}"></label></div></article>`).join('')}</div><div class="panel rules"><h2>Regras de distribuição</h2><ol><li>Prioriza a dona da carteira se estiver disponível e com capacidade.</li><li>Na cobertura, escolhe a disponível com menos atendimentos abertos.</li><li>Em empate, escolhe quem está há mais tempo sem receber.</li><li>Atendimentos aguardando cliente ou ação interna contam na carga.</li><li>Somente gerente e gestor podem alterar carteiras.</li></ol><p>A simulação de perfis ajuda a revisar os fluxos. Permissões reais e isolamento entre empresas exigem o servidor da próxima etapa.</p></div>`;}
function integrations(){return heading('CANAIS PREPARADOS PARA EVOLUIR','Canais e integrações','Comece com registros manuais e conecte cada serviço quando for aprovado.')+`<div class="integration-grid">${CHANNELS.map((ch,i)=>`<article class="panel integration"><div class="integration-top"><span class="channel-icon">${['◉','◎','☏','✉','▤','☎'][i]}</span>${chip('Registro manual','muted')}</div><h2>${ch}</h2><p>${ch==='WhatsApp'?'Mantenha o WhatsApp Business no celular. Abertura de conversa pelo aplicativo, sem sincronização.':'Identifique a origem e registre as interações no histórico do cliente.'}</p><div class="integration-bottom"><span class="status-dot"></span>Integração automática desativada</div></article>`).join('')}<article class="panel integration"><div class="integration-top"><span class="channel-icon">W</span>${chip('Futuro','muted')}</div><h2>TOTVS WinThor</h2><p>Preparado no planejamento para consulta de preços, clientes e pedidos. Nenhuma conexão ativa.</p><div class="integration-bottom"><span class="status-dot"></span>Sem acesso a preços ou estoque</div></article><article class="panel integration"><div class="integration-top"><span class="channel-icon">✦</span>${chip('Futuro','muted')}</div><h2>Assistente de IA</h2><p>Resumos e sugestões de resposta previstos. Nenhuma mensagem ou dado é enviado a modelos nesta versão.</p><div class="integration-bottom"><span class="status-dot"></span>Assistente desativado</div></article></div>`;}
function auditPage(){const logs=scoped(s.audit);return heading('TRANSPARÊNCIA DA OPERAÇÃO','Histórico de alterações','Movimentações de carteira, atribuições e mudanças registradas nesta demonstração.')+`<section class="panel">${logs.length?logs.map(a=>`<div class="audit-row"><span class="audit-dot"></span><div><strong>${esc(a.action)}</strong><p>${esc(a.detail)}</p><small>${esc(a.actor)} · ${when(a.at)}</small></div></div>`).join(''):empty('Histórico ainda vazio','As próximas alterações aparecerão aqui.')}</section>`;}
function showModal(title,body,wide=false){const m=$('#modal');m.className=wide?'wide':'';m.innerHTML=`<div class="modal-heading"><div><p class="eyebrow">KALBIR CRM</p><h2 id="modal-title">${title}</h2></div><button class="icon-button" data-action="close" aria-label="Fechar">✕</button></div>${body}`;if(!m.open)m.showModal();}
function opts(values,selected){return values.map(v=>`<option value="${esc(typeof v==='object'?v.value:v)}" ${(typeof v==='object'?v.value:v)===selected?'selected':''}>${esc(typeof v==='object'?v.label:v)}</option>`).join('');}
function input(label,name,value='',type='text',required=false,attrs=''){return `<label>${label}${required?' <span class="required">*</span>':''}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${attrs}></label>`;}
function select(label,name,values,value){return `<label>${label}<select name="${name}">${opts(values,value)}</select></label>`;}
const submit=label=>`<p class="form-error" role="alert"></p><div class="form-actions">${btn('Cancelar','close')}<button class="primary" type="submit">${label}</button></div>`;
function clientForm(id){const c=id?client(id):{name:'',phone:'',email:'',handle:'',channel:'WhatsApp',status:'Novo',segments:[],days:[],storeId:actor().storeId};if(id&&!clients().some(x=>x.id===id))throw Error('Cliente fora do seu acesso.');showModal(id?'Editar cliente':'Novo cliente',`<form id="client-form" data-id="${id||''}"><p class="form-intro">Nome e ao menos uma forma de contato são necessários. Complete os dados comerciais durante o relacionamento.</p><div class="form-grid">${input('Nome','name',c.name,'text',true)}${input('Empresa do cliente','company',c.company)}${input('Pessoa de contato','contact',c.contact)}${select('Canal principal','channel',CHANNELS,c.channel)}${input('Telefone / WhatsApp com DDD','phone',c.phone,'tel')}${input('E-mail','email',c.email,'email')}${input('Identificação no canal','handle',c.handle,'text',false,'placeholder="Ex.: @cliente"')}${select('Status','status',['Novo','Em qualificação','Cliente ativo','Inativo'],c.status)}${input('Código externo / WinThor','externalCode',c.externalCode)}${select('Origem','origin',['Cadastro manual','Redes sociais','Indicação','Importação','Cliente existente'],c.origin||'Cadastro manual')}${input('Loja preferencial','storeLabel','Loja piloto','text',false,'readonly')}${input('Rota de atendimento / entrega','route',c.route)}</div><fieldset><legend>Segmentos</legend><div class="checkbox-grid">${SEGMENTS.map(x=>`<label><input type="checkbox" name="segments" value="${esc(x)}" ${c.segments.includes(x)?'checked':''}>${x}</label>`).join('')}</div></fieldset><fieldset><legend>Dias preferidos de compra</legend><div class="checkbox-grid days">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>`<label><input type="checkbox" name="days" value="${x}" ${c.days.includes(x)?'checked':''}>${x}</label>`).join('')}</div></fieldset><label>Observações<textarea name="notes" rows="3">${esc(c.notes||'')}</textarea></label><label class="check-label"><input type="checkbox" name="doNotContact" ${c.doNotContact?'checked':''}>Não realizar contato ativo com este cliente</label><p class="form-help">Carteira: ${esc(ownerLabel(c.ownerId))}. Alterações de carteira são feitas separadamente pela gestão, com motivo.</p>${submit('Salvar cliente')}</form>`,true);}
function clientDetail(id){const c=client(id);if(!clients().some(x=>x.id===id))throw Error('Cliente fora do seu acesso.');const ts=tickets().filter(t=>t.clientId===id);showModal(esc(c.name),`<div class="detail-tags">${chip(c.status,'green')}${chip(c.channel)}${c.doNotContact?chip('Não contatar','amber'):''}</div><div class="detail-grid"><div><small>Carteira</small><strong>${esc(ownerLabel(c.ownerId))}</strong></div><div><small>Pessoa de contato</small><strong>${esc(c.contact||'Não informada')}</strong></div><div><small>Telefone</small><strong>${esc(c.phone||'Não informado')}</strong></div><div><small>E-mail / identificação</small><strong>${esc(c.email||c.handle||'Não informado')}</strong></div><div><small>Segmentos</small><strong>${esc(c.segments.join(', ')||'Não informado')}</strong></div><div><small>Rota / dias preferidos</small><strong>${esc(c.route||'Sem rota')} · ${esc(c.days.join(', ')||'Não informados')}</strong></div></div><p class="detail-note">${esc(c.notes||'Sem observações.')}</p><div class="detail-actions">${btn('Editar cadastro','edit-client',id,'primary')}${canManage(actor())?btn('Alterar carteira','owner',id):''}${btn('Novo atendimento','new-ticket-client',id)}</div><h3 class="subheading">Atendimentos e histórico</h3>${ts.length?ts.map(t=>`<div class="history-block">${ticketRow(t)}${t.activities.map(a=>`<div class="activity"><strong>${esc(a.kind)}</strong><p>${esc(a.text)}</p><small>${esc(a.by)} · ${when(a.at)}</small></div>`).join('')}</div>`).join(''):empty('Nenhum atendimento','Registre o primeiro contato deste cliente.')}`,true);}
function ticketDetail(id){const t=tickets().find(t=>t.id===id);if(!t)throw Error('Atendimento fora do seu acesso.');const c=client(t.clientId);showModal(esc(c.name),`<div class="detail-tags">${statusChip(t.status)}${chip(c.channel)}${chip('#'+t.id.replace('t',''))}</div><h3>${esc(t.subject)}</h3><p class="form-help">Carteira: ${esc(ownerLabel(c.ownerId))} · Atendimento: ${esc(ownerLabel(t.assigneeId))}</p><div class="detail-actions">${btn('Ficha do cliente','client',c.id)}${c.phone&&c.channel==='WhatsApp'&&!c.doNotContact?`<a class="secondary button-link" href="https://wa.me/${normalizePhone(c.phone)}" target="_blank" rel="noopener noreferrer">Abrir WhatsApp ↗</a>`:''}${c.email&&c.channel==='E-mail'&&!c.doNotContact?`<a class="secondary button-link" href="mailto:${esc(c.email)}">Abrir e-mail ↗</a>`:''}${canManage(actor())&&t.status!=='Encerrado'?btn('Atribuir / transferir','assign',id):''}${actor().role==='vendedora'&&t.status==='Em fila'?btn('Puxar atendimento','claim',id,'primary'):''}</div>${c.doNotContact?'<p class="warning">Cliente com restrição de contato ativo. Respeite sua preferência.</p>':''}${!c.phone&&c.channel==='WhatsApp'?'<p class="info-line">Cadastro fictício sem telefone. Informe um número válido para abrir o WhatsApp.</p>':''}${t.status!=='Em fila'&&t.status!=='Encerrado'?`<form id="ticket-form" data-id="${id}"><div class="form-grid">${select('Situação','status',[...OPEN,'Encerrado'],t.status)}${select('Tipo de registro','kind',['Nota interna','Mensagem registrada','Ligação registrada','Retorno realizado'],'Nota interna')}${input('Próxima ação','nextAction',t.nextAction)}${input('Data e hora do retorno','nextAt',t.nextAt,'datetime-local')}</div><label>Registro da interação<textarea name="text" rows="3" placeholder="Descreva o contato ou a ação realizada"></textarea></label>${select('Resultado (obrigatório ao encerrar)','result',['','Demanda resolvida','Orçamento encaminhado','Retorno agendado','Sem interesse','Sem resposta','Cadastro duplicado'],t.result||'')}<p class="form-help">Registros são manuais. Salvar não envia mensagens ao cliente. Para aguardar, informe a próxima ação e o retorno.</p>${submit('Salvar atendimento')}</form>`:''}<h3 class="subheading">Histórico deste atendimento</h3>${t.activities.length?t.activities.map(a=>`<div class="activity"><strong>${esc(a.kind)}</strong><p>${esc(a.text)}</p><small>${esc(a.by)} · ${when(a.at)}</small></div>`).join(''):'<p class="muted-text">Nenhuma interação registrada.</p>'}${t.status==='Encerrado'?`<p>Resultado: <strong>${esc(t.result)}</strong></p>${btn('Reabrir atendimento','reopen',id)}`:''}`,true);}
function assignForm(id){if(!canManage(actor()))throw Error('Acesso restrito à gestão.');const t=tickets().find(t=>t.id===id);if(!t)throw Error('Atendimento não encontrado.');showModal('Atribuir atendimento',`<form id="assign-form" data-id="${id}"><p class="form-intro">Transferir o atendimento preserva a dona da carteira.</p>${select('Responsável','userId',scoped(s.users).filter(u=>u.role==='vendedora').map(u=>({value:u.id,label:`${u.name} · ${u.availability} · ${load(s,u.id)}/${u.capacity}`})),'')}${input('Motivo','reason','','text',true)}${submit('Confirmar atribuição')}</form>`);}
function ownerForm(id){if(!canManage(actor()))throw Error('Acesso restrito à gestão.');const c=client(id);showModal('Alterar carteira',`<form id="owner-form" data-id="${id}"><p class="form-intro">Cliente: <strong>${esc(c.name)}</strong>. Esta mudança altera a responsabilidade comercial.</p>${select('Nova responsável','ownerId',[{value:'',label:'Sem responsável'},...scoped(s.users).filter(u=>u.role==='vendedora').map(u=>({value:u.id,label:u.name}))],c.ownerId)}${input('Motivo da alteração','reason','','text',true)}${submit('Alterar carteira')}</form>`);}
function newTicket(clientId=''){const cs=clients();if(!cs.length){clientForm();return;}showModal('Registrar entrada',`<form id="new-ticket-form">${select('Cliente','clientId',cs.map(c=>({value:c.id,label:c.name})),clientId||cs[0].id)}${input('Assunto / necessidade','subject','','text',true)}${select('Prioridade','priority',['Normal','Alta'],'Normal')}<p class="form-help">A entrada será registrada na fila. Use a distribuição automática ou atribua uma responsável.</p>${submit('Adicionar à fila')}</form>`);}
function opportunityForm(id){const o=id?opportunities().find(o=>o.id===id):null;if(id&&!o)throw Error('Oportunidade fora do seu acesso.');const cs=clients();if(!cs.length){clientForm();return;}showModal(id?'Atualizar oportunidade':'Nova oportunidade',`<form id="opportunity-form" data-id="${id||''}">${input('Título da oportunidade','title',o?.title,'text',true)}<div class="form-grid">${select('Cliente','clientId',cs.map(c=>({value:c.id,label:c.name})),o?.clientId||cs[0].id)}${select('Etapa','stage',STAGES,o?.stage||STAGES[0])}${input('Valor estimado (R$)','value',o?.value||0,'number',true,'min="0" step="0.01"')}${select('Responsável','ownerId',scoped(s.users).filter(u=>u.role==='vendedora'&&(canManage(actor())||u.id===actorId)).map(u=>({value:u.id,label:u.name})),o?.ownerId||(actor().role==='vendedora'?actorId:'v1'))}${input('Próxima ação','nextAction',o?.nextAction)}${input('Data do retorno','nextAt',o?.nextAt,'datetime-local')}</div>${input('Fonte / data dos preços','priceSource',o?.priceSource||'Valor informado manualmente — sem consulta ao ERP','text',true)}<p class="form-help">A oportunidade permanece independente do estado do atendimento. Não há emissão de orçamento ou pedido nesta etapa.</p>${submit('Salvar oportunidade')}</form>`,true);}
function exportData(){const blob=new Blob([JSON.stringify({...s,exportedAt:new Date().toISOString(),demo:true},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='kalbir-crm-demonstracao.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Arquivo de demonstração exportado.');}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action],[data-page]');if(!target)return;const a=target.dataset.action,id=target.dataset.id;try{if(target.dataset.page){page=target.dataset.page;query='';render();return;}if(a?.startsWith('go-')){page=a.slice(3);query='';render();return;}switch(a){case'menu':$('.sidebar').classList.toggle('mobile-open');break;case'close':$('#modal').close();break;case'export':exportData();break;case'new-client':clientForm();break;case'edit-client':clientForm(id);break;case'client':clientDetail(id);break;case'ticket':ticketDetail(id);break;case'owner':ownerForm(id);break;case'assign':assignForm(id);break;case'new-ticket':newTicket();break;case'new-ticket-client':newTicket(id);break;case'new-opportunity':opportunityForm();break;case'opportunity':opportunityForm(id);break;case'claim':claim(s,id,actor());save();render();if($('#modal').open)$('#modal').close();toast('Atendimento atribuído a você. Carteira preservada.');break;case'auto-assign':{if(!canManage(actor()))throw Error('Acesso restrito à gestão.');let n=0;scoped(s.tickets).filter(t=>t.status==='Em fila').sort((a,b)=>(b.priority==='Alta')-(a.priority==='Alta')||a.createdAt-b.createdAt).forEach(t=>{const u=chooseAgent(s,client(t.clientId));if(u){assign(s,t.id,u.id,actor(),'Distribuição automática');n++;}});save();render();toast(n?`${n} atendimento(s) distribuído(s).`:'Nenhuma vendedora disponível com capacidade.');break;}case'reopen':{const t=tickets().find(t=>t.id===id);if(!t)throw Error('Atendimento fora do seu acesso.');if(!canManage(actor())&&t.assigneeId!==actorId)throw Error('Sem permissão.');t.status='Em fila';t.assigneeId='';t.result='';audit(s,actor(),'Atendimento reaberto',t.id);save();render();$('#modal').close();toast('Atendimento reaberto e devolvido à fila.');break;}case'new-user':if(!canManage(actor()))throw Error('Acesso restrito.');showModal('Adicionar vendedora',`<form id="user-form">${input('Nome','name','','text',true)}${input('Limite simultâneo','capacity',5,'number',true,'min="1" max="50"')}<p class="form-help">Cria apenas um perfil de demonstração. Não envia convite nem cria login.</p>${submit('Adicionar ao piloto')}</form>`);break;}}catch(err){toast(err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;$('#page-content').innerHTML=({work,queue,clients:clientPage,pipeline}[page])();const input=$('#search');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{try{if(e.target.id==='actor-select'){actorId=e.target.value;query='';clientFilter='Todos';ticketFilter='Todos';render();return;}if(e.target.id==='client-filter'){clientFilter=e.target.value;render();return;}if(e.target.id==='ticket-filter'){ticketFilter=e.target.value;render();return;}if(e.target.matches('.availability,.capacity')){if(!canManage(actor()))throw Error('Acesso restrito.');const u=scoped(s.users).find(u=>u.id===e.target.dataset.user);if(!u)throw Error('Perfil fora do seu acesso.');if(e.target.matches('.capacity')){const n=Number(e.target.value);if(!Number.isInteger(n)||n<1||n>50)throw Error('O limite deve ser de 1 a 50.');u.capacity=n;}else u.availability=e.target.value;audit(s,actor(),'Disponibilidade / capacidade',`${u.name}: ${u.availability}, limite ${u.capacity}`);save();render();toast('Equipe atualizada.');}}catch(err){toast(err.message);render();}});
document.addEventListener('submit',e=>{if(!e.target.closest('#modal'))return;e.preventDefault();const form=e.target,fd=new FormData(form),data=Object.fromEntries(fd),id=form.dataset.id;try{switch(form.id){case'client-form':{const old=id?client(id):null;const c={...(old||{id:crypto.randomUUID(),tenantId:actor().tenantId,storeId:actor().storeId,ownerId:actor().role==='vendedora'?actorId:'',createdAt:Date.now()}),...data,segments:fd.getAll('segments'),days:fd.getAll('days'),doNotContact:fd.has('doNotContact')};delete c.storeLabel;validateClient(c);const dup=duplicates(s,c);if(dup.length)throw Error(`Possível duplicidade com ${dup[0].name}. Revise o contato antes de salvar.`);if(old){if(!clients().some(x=>x.id===id))throw Error('Sem acesso ao cliente.');Object.assign(old,c);}else s.clients.push(c);audit(s,actor(),old?'Cadastro atualizado':'Cliente cadastrado',c.name);break;}case'owner-form':changeOwner(s,id,data.ownerId,actor(),data.reason);break;case'assign-form':if(!data.reason.trim())throw Error('Informe o motivo.');assign(s,id,data.userId,actor(),data.reason);break;case'new-ticket-form':{const c=clients().find(c=>c.id===data.clientId);if(!c)throw Error('Cliente inválido.');s.tickets.push({id:'t'+Date.now(),tenantId:c.tenantId,storeId:c.storeId,clientId:c.id,subject:data.subject.trim(),priority:data.priority,status:'Em fila',assigneeId:'',createdAt:Date.now(),updatedAt:Date.now(),activities:[],nextAction:'',nextAt:'',result:''});audit(s,actor(),'Entrada na fila',c.name);break;}case'ticket-form':{const t=tickets().find(t=>t.id===id);if(!t||(!canManage(actor())&&t.assigneeId!==actorId))throw Error('Sem permissão para editar.');if(data.status==='Encerrado'&&!data.result)throw Error('Informe o resultado ao encerrar.');if(data.status.startsWith('Aguardando')&&(!data.nextAction.trim()||!data.nextAt))throw Error('Informe a próxima ação e a data do retorno.');Object.assign(t,{status:data.status,nextAction:data.nextAction.trim(),nextAt:data.nextAt,result:data.status==='Encerrado'?data.result:'',updatedAt:Date.now()});if(data.text.trim())t.activities.unshift({kind:data.kind,text:data.text.trim(),by:actor().name,at:Date.now()});audit(s,actor(),'Atendimento atualizado',`${t.id} · ${t.status}`);break;}case'opportunity-form':{const c=clients().find(c=>c.id===data.clientId);if(!c)throw Error('Cliente inválido.');if(!['Ganho','Perdido'].includes(data.stage)&&!data.nextAction.trim())throw Error('Defina a próxima ação da oportunidade.');if(!Number.isFinite(Number(data.value))||Number(data.value)<0)throw Error('Valor inválido.');const u=scoped(s.users).find(u=>u.id===data.ownerId&&u.role==='vendedora');if(!u||(!canManage(actor())&&u.id!==actorId))throw Error('Responsável inválida.');const o={...data,value:Number(data.value)};if(id){const old=opportunities().find(x=>x.id===id);if(!old)throw Error('Sem acesso.');Object.assign(old,o);}else s.opportunities.push({...o,id:crypto.randomUUID(),tenantId:c.tenantId,storeId:c.storeId});audit(s,actor(),'Oportunidade atualizada',`${o.title} · ${o.stage}`);break;}case'user-form':{if(!canManage(actor()))throw Error('Acesso restrito.');const capacity=Number(data.capacity);if(!Number.isInteger(capacity)||capacity<1||capacity>50)throw Error('Limite inválido.');s.users.push({id:crypto.randomUUID(),tenantId:actor().tenantId,storeId:actor().storeId,name:data.name.trim(),role:'vendedora',availability:'Disponível',capacity,lastAssigned:0});audit(s,actor(),'Perfil de demonstração adicionado',data.name);break;}default:return;}save();$('#modal').close();render();toast('Alteração salva nesta demonstração.');}catch(err){form.querySelector('.form-error').textContent=err.message;}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
render();
